{
  "name": "wallet_auto_balance",
  "project_id": "mxmfbzpbcnaapcxdggkf",
  "query": "alter table public.wallets\n  add column opening_balance numeric(14,2) not null default 0;\n\nupdate public.wallets set opening_balance = balance;\n\ncreate function public.txn_effect(p_type text, p_amount numeric, p_wallet_type text)\nreturns numeric\nlanguage sql immutable set search_path = '' as $$\n  select case\n    when p_wallet_type = 'creditCard'\n      then case when p_type = 'expense' then p_amount else -p_amount end\n    else case when p_type = 'income' then p_amount else -p_amount end\n  end\n$$;\n\ncreate function public.apply_wallet_balance() returns trigger\nlanguage plpgsql set search_path = '' as $$\nbegin\n  if tg_op <> 'INSERT' then\n    if old.wallet_id is not null and old.is_paid then\n      update public.wallets w\n         set balance = w.balance - public.txn_effect(old.type, old.amount, w.type)\n       where w.id = old.wallet_id;\n    end if;\n  end if;\n\n  if tg_op <> 'DELETE' then\n    if new.wallet_id is not null and new.is_paid then\n      update public.wallets w\n         set balance = w.balance + public.txn_effect(new.type, new.amount, w.type)\n       where w.id = new.wallet_id;\n    end if;\n  end if;\n\n  if tg_op = 'DELETE' then\n    return old;\n  end if;\n  return new;\nend $$;\n\ncreate trigger transactions_wallet_balance\n  after insert or update of wallet_id, amount, type, is_paid or delete\n  on public.transactions\n  for each row execute function public.apply_wallet_balance();\n\ncreate function public.recalculate_wallet_balances() returns void\nlanguage sql set search_path = '' as $$\n  update public.wallets w\n     set balance = w.opening_balance + coalesce((\n       select sum(public.txn_effect(t.type, t.amount, w.type))\n         from public.transactions t\n        where t.wallet_id = w.id and t.is_paid\n     ), 0)\n   where w.user_id = (select auth.uid());\n$$;\n\nrevoke all on function public.recalculate_wallet_balances() from public, anon;\ngrant execute on function public.recalculate_wallet_balances() to authenticated;"
}
